function normalizePunctuation(str){if(!str)return"";return String(str).replace(/[\u2010-\u2015\u2212\uFE58\uFE63\uFF0D]/g,"-").replace(/[\u2018-\u201B\u2032\uFF07]/g,"'").replace(/[\u201C-\u201F\u2033\uFF02]/g,'"').replace(/[\u00A0\u2000-\u200B\u3000]/g," ").replace(/[\u2026]/g,"...").replace(/\s+/g," ").trim().toLowerCase();}
let isPracticing=false,timerInterval=null,timerStartTime=0;
function startTimer(){isPracticing=true;timerStartTime=Date.now();exerciseStartTime=timerStartTime;document.getElementById("timerBadge").style.display="block";updateTimerDisplay();clearInterval(timerInterval);timerInterval=setInterval(updateTimerDisplay,1000);}
function updateTimerDisplay(){const e=Math.floor((Date.now()-timerStartTime)/1000);const m=String(Math.floor(e/60)).padStart(2,"0");const s=String(e%60).padStart(2,"0");document.getElementById("timerBadge").innerText=`⏱ ${m}:${s}`;}
function stopTimer(){isPracticing=false;clearInterval(timerInterval);timerInterval=null;document.getElementById("timerBadge").style.display="none";}
function guardNavigation(){if(!isPracticing)return true;const ok=confirm("⚠️ 練習進行中，離開將丟失本次進度。\n\n點擊『確定』：自動保存本次成績並退出\n點擊『取消』：繼續練習");if(ok){saveCurrentQuizSilently();stopTimer();return true;}return false;}
function saveCurrentQuizSilently(){try{if(quizType==="write"&&window._writeScore)saveWriteRecord(true);else if(quizType==="cloze"&&window._clozeScore)saveClozeRecord(true);else if(quizType==="choice"&&window._choiceScore)saveChoiceRecord(true);else if(quizType==="grammar"&&window._grammarScore)saveGrammarRecord(true);}catch(e){}}
document.getElementById("disclaimerModal").style.display="flex";
