(function(){const b=document.getElementById("eyeCareBanner");let a=false,c=false,d=false;const st=Date.now();function sh(t,cl){b.innerText=t;b.className="show "+cl;setTimeout(()=>b.classList.remove("show"),6000);}setInterval(function(){const m=Math.floor((Date.now()-st)/60000);if(m>=15&&!a){a=true;sh("👀 已看 15 分鐘，看看遠處放鬆一下眼睛吧～","green");}if(m>=30&&!c){c=true;sh("🚶 已看 30 分鐘，建議站起來活動一下。","yellow");}if(m>=60&&!d){d=true;sh("❤️ 已看 1 小時，該休息了！","red");}},30000);})();
function goHome(){hideAllBox();document.getElementById("homePage").style.display="block";document.getElementById("moduleView").style.display="none";document.getElementById("backHomeBtn").style.display="none";renderHomeGrid();updateHomeStats();setTimeout(()=>window.scrollTo(0,homeScrollY),10);}
function hideAllBox(){document.querySelectorAll(".box-wrap").forEach(el=>el.classList.remove("show"));}
function showRoot(id){if(!guardNavigation())return;if(document.getElementById("homePage").style.display!=="none"){homeScrollY=window.scrollY;}hideAllBox();document.getElementById("homePage").style.display="none";document.getElementById("moduleView").style.display="block";document.getElementById("backHomeBtn").style.display="block";document.getElementById("backHomeBtn").innerText="← 返回首頁";if(id==="vocabPool")renderVocabUnits();if(id==="exerciseRoot")renderExerciseUnits();document.getElementById(id).classList.add("show");setTimeout(()=>window.scrollTo(0,0),10);}
function goBack(){if(!guardNavigation())return;const backBtn=document.getElementById("backHomeBtn");const rSub=document.getElementById("readingSubPanel"),rPan=document.getElementById("readingPanel"),vUnit=document.getElementById("vocabUnit"),eUnit=document.getElementById("exerciseUnit"),gPan=document.getElementById("grammarPanel"),gRoot=document.getElementById("grammarRoot"),rRoot=document.getElementById("readingRoot"),wRedo=document.getElementById("wrongRedoPanel");if(rSub&&rSub.innerHTML.trim()!==""&&rRoot&&rRoot.classList.contains("show")){rSub.innerHTML="";openReadingUnit(currentReadingUnit);backBtn.innerText="← 返回首頁";return;}if(rPan&&rPan.innerHTML.trim()!==""&&rRoot&&rRoot.classList.contains("show")){rPan.innerHTML="";showRoot("readingRoot");backBtn.innerText="← 返回首頁";return;}if(vUnit&&vUnit.classList.contains("show")){showRoot("vocabPool");backBtn.innerText="← 返回首頁";return;}if(eUnit&&eUnit.classList.contains("show")){showRoot("exerciseRoot");backBtn.innerText="← 返回首頁";return;}if(gPan&&gPan.innerHTML.trim()!==""&&gRoot&&gRoot.classList.contains("show")){gPan.innerHTML="";showRoot("grammarRoot");backBtn.innerText="← 返回首頁";return;}if(wRedo&&wRedo.classList.contains("show")){showRoot("wrongBookPanel");backBtn.innerText="← 返回首頁";return;}goHome();}
function renderHomeGrid(){const grid=document.getElementById("homeGrid");if(!grid)return;const cards=[{icon:"📚",title:"生詞池",desc:"卡片 + 表格瀏覽，同義詞發音，可下載 CSV",tags:["發音","表格","下載"],target:"vocabPool"},{icon:"📝",title:"練習題",desc:"默寫、完形填空、拖拽選擇，三種題型",tags:["默寫","完形","拖拽"],target:"exerciseRoot"},{icon:"📖",title:"語法",desc:"動詞表 + 時態結構 + 測驗",tags:["動詞表","時態","選擇題"],target:"grammarRoot"},{icon:"📘",title:"閱讀理解",desc:"文章閱讀 + 語境完形，點擊查詞",tags:["閱讀","查詞","測驗"],target:"readingRoot"},{icon:"📒",title:"錯題本",desc:"保存每次成績，可重做錯題",tags:["記錄","重做","複習"],target:"wrongBookPanel"}];grid.innerHTML="";cards.forEach(c=>{const card=document.createElement("div");card.className="module-card";card.innerHTML=`<div class="card-icon">${c.icon}</div><div class="card-title">${c.title}</div><div class="card-desc">${c.desc}</div><div class="card-tags">${c.tags.map(t=>`<span class="tag">${t}</span>`).join("")}</div><button class="card-btn">進入 →</button>`;card.onclick=()=>{if(c.target==="wrongBookPanel"){openWrongBook();}else{showRoot(c.target);}};grid.appendChild(card);});}
function updateHomeStats(){try{const wc=Object.values(WORD_UNITS).reduce((s,a)=>s+a.length,0);const cc=Object.values(CLOZE_UNITS).reduce((s,a)=>s+a.length,0);const gc=(typeof GRAMMAR_BANK!=="undefined")?GRAMMAR_BANK.length:0;const rc=(typeof READING_UNITS!=="undefined")?Object.keys(READING_UNITS).length:0;document.getElementById("statWords").innerText=wc;document.getElementById("statCloze").innerText=cc;document.getElementById("statGrammar").innerText=gc;document.getElementById("statReading").innerText=rc;}catch(e){}}
document.addEventListener("dragover",function(e){if(!draggingWordEl)return;e.preventDefault();const y=e.clientY,t=120,s=15;if(y>window.innerHeight-t)window.scrollBy(0,s);else if(y<t)window.scrollBy(0,-s);});
document.addEventListener("touchmove",function(e){if(!draggingWordEl)return;const y=e.touches[0].clientY,t=120,s=15;if(y>window.innerHeight-t)window.scrollBy(0,s);else if(y<t)window.scrollBy(0,-s);},{passive:false});
